CREATE OR REPLACE FUNCTION public.icash_mark_inventory_empty(p_account uuid, p_revision uuid, p_page integer)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 update public.icash_discovery_configs set exhausted=true where account_id=p_account and revision=p_revision and next_page=p_page;
 if found then
 update public.icash_inventory_markets set next_scan_at=now()+interval '30 days' where account_id=p_account and zip=(select zip from public.icash_discovery_configs where account_id=p_account);
 perform public.icash_rotate_inventory_market(p_account);
 end if;
end $function$

CREATE OR REPLACE FUNCTION public.icash_rotate_inventory_market(p_account uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare c public.icash_discovery_configs;m public.icash_inventory_markets;
begin
 select * into c from public.icash_discovery_configs where account_id=p_account for update;
 if not found or not c.exhausted or not c.enabled or not c.auto_enabled or c.data_rights_until<=now() then return false;end if;
 if not exists(select 1 from public.icash_accounts a join public.icash_wallets w on w.account_id=a.id where a.id=p_account and not a.bot_paused and w.balance_cents>w.reserved_cents) then return false;end if;
 select icash_inventory_markets.* into m from (select account_id,zip from public.icash_inventory_markets where account_id=p_account and eligible_until>now() and next_scan_at<=now() and public.icash_research_zip_known(zip) and public.icash_inventory_scope_allowed(p_account,zip) and not public.icash_stalled_research_zip(p_account,zip) order by priority,md5(zip||p_account::text) limit 64) candidates
   join public.icash_inventory_markets using(account_id,zip) order by (select count(*) from public.icash_discovery_configs other where other.zip=icash_inventory_markets.zip and other.account_id<>p_account and other.enabled and not other.exhausted),public.icash_opportunity_market_score(p_account,zip) desc,priority,zip for update of icash_inventory_markets skip locked limit 1;
 if not found then return false;end if;
 update public.icash_discovery_configs set zip=m.zip,next_page=1,revision=gen_random_uuid(),exhausted=false where account_id=p_account;
 update public.icash_inventory_markets set next_scan_at=now()+interval '30 days' where account_id=p_account and zip=m.zip;
 return true;
end $function$
